def work_on_strings(a, b):
    def swap_case(s, chars):
        for char in chars:
            count = s.lower().count(char.lower())
            for _ in range(count):
                s = ''.join(c.swapcase() if c.lower() == char.lower() else c for c in s)
        return s

    a_changed = swap_case(a, b)
    b_changed = swap_case(b, a)

    return a_changed + b_changed
